import { useState, useRef } from 'react';
import {
  Video,
  Upload,
  Trash2,
  Eye,
  AlertCircle,
  CheckCircle2,
  RefreshCw,
  Settings as SettingsIcon,
  Film,
  Home,
  Building2,
} from 'lucide-react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Switch } from '@/components/ui/switch';
import { Label } from '@/components/ui/label';
import { Input } from '@/components/ui/input';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog';
import { useFactoryVideo } from '@/hooks/useFactoryVideo';
import { useSyncService } from '@/context/SyncServiceContext';
import { useI18n } from '@/i18n/I18nContext';
import PageBreadcrumb from '@/components/PageBreadcrumb';
import FactoryVideoPlayer from '@/components/FactoryVideoPlayer';
import { toast } from 'sonner';

const MAX_SIZE_MB = 100;

type UploadTarget = 'home' | 'about';

export default function AdminFactoryVideoPage() {
  const { adminT } = useI18n();
  const {
    settings,
    homeVideo,
    aboutVideo,
    loading,
    saving,
    updateSettings,
    uploadVideo,
    resetVideo,
  } = useFactoryVideo();
  const { markDirty } = useSyncService();

  const [dragTarget, setDragTarget] = useState<UploadTarget | null>(null);
  const [resetTarget, setResetTarget] = useState<UploadTarget | null>(null);
  const homeInputRef = useRef<HTMLInputElement>(null);
  const aboutInputRef = useRef<HTMLInputElement>(null);

  // 修改后标记 dirty
  const handleUpdate = (updates: Parameters<typeof updateSettings>[0]) => {
    updateSettings(updates);
    markDirty('factoryVideo');
  };

  const handleFileSelect = async (target: UploadTarget, file: File | undefined | null) => {
    if (!file) return;

    // 类型校验
    if (!file.type.startsWith('video/') && !/\.(mp4|webm|ogg|mov)$/i.test(file.name)) {
      toast.error('文件类型错误：仅支持 MP4 / WebM / MOV 视频文件');
      return;
    }

    // 大小校验
    if (file.size > MAX_SIZE_MB * 1024 * 1024) {
      toast.error(
        `文件过大：最大支持 ${MAX_SIZE_MB}MB，当前文件 ${(file.size / 1024 / 1024).toFixed(1)}MB`
      );
      return;
    }

    const ok = await uploadVideo(target, file);
    if (ok) {
      toast.success(`${target === 'home' ? '首页' : 'About 页面'}视频已更新`);
      markDirty('factoryVideo');
    } else {
      toast.error('上传失败，请稍后重试');
    }
    setDragTarget(null);
  };

  const handleReset = async (target: UploadTarget) => {
    const ok = await resetVideo(target);
    if (ok) {
      toast.success('已恢复默认视频');
      markDirty('factoryVideo');
    } else {
      toast.error('操作失败');
    }
    setResetTarget(null);
  };

  const handleDrop = (e: React.DragEvent<HTMLDivElement>, target: UploadTarget) => {
    e.preventDefault();
    const file = e.dataTransfer.files?.[0];
    handleFileSelect(target, file);
  };

  const formatSize = (bytes: number) => {
    if (bytes === 0) return '-';
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
    return `${(bytes / 1024 / 1024).toFixed(2)} MB`;
  };

  // 上传卡片
  const UploadCard = ({
    target,
    title,
    desc,
    videoInfo,
    icon: Icon,
  }: {
    target: UploadTarget;
    title: string;
    desc: string;
    videoInfo: typeof homeVideo;
    icon: typeof Home;
  }) => {
    const inputRef = target === 'home' ? homeInputRef : aboutInputRef;
    const isDragOver = dragTarget === target;

    return (
      <Card className="border-border/40 bg-card">
        <CardHeader>
          <CardTitle className="text-base flex items-center gap-2">
            <Icon className="size-4 text-primary" />
            {title}
          </CardTitle>
          <CardDescription>{desc}</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          {/* 当前视频信息 */}
          <div className="flex items-start gap-3 p-3 rounded-lg bg-muted/30 border border-border/40">
            <div className="size-10 shrink-0 rounded-md bg-primary/10 flex items-center justify-center">
              <Film className="size-5 text-primary" />
            </div>
            <div className="flex-1 min-w-0">
              <div className="text-sm font-medium text-foreground truncate" title={videoInfo.name || '未设置'}>
                {videoInfo.name || '未上传视频'}
              </div>
              <div className="text-xs text-muted-foreground mt-0.5">
                {formatSize(videoInfo.size)}
              </div>
              {videoInfo.isCustom && videoInfo.uploadDate && (
                <div className="text-xs text-muted-foreground mt-0.5">
                  上传时间：{new Date(videoInfo.uploadDate).toLocaleString()}
                </div>
              )}
            </div>
            <Badge
              variant="outline"
              className={
                videoInfo.isCustom
                  ? 'bg-success/15 text-success border-success/30'
                  : 'bg-muted/50'
              }
            >
              {videoInfo.isCustom ? (
                <>
                  <CheckCircle2 className="size-3 mr-1" />
                  已上传
                </>
              ) : (
                <>
                  <AlertCircle className="size-3 mr-1" />
                  未设置
                </>
              )}
            </Badge>
          </div>

          {/* 上传区域 */}
          <div
            onDrop={(e) => handleDrop(e, target)}
            onDragOver={(e) => {
              e.preventDefault();
              setDragTarget(target);
            }}
            onDragLeave={() => setDragTarget(null)}
            onClick={() => inputRef.current?.click()}
            className={`relative border-2 border-dashed rounded-lg p-5 text-center transition-colors cursor-pointer ${
              isDragOver
                ? 'border-primary bg-primary/5'
                : 'border-border/60 hover:border-primary/50 hover:bg-muted/30'
            }`}
          >
            <input
              ref={inputRef}
              type="file"
              accept="video/mp4,video/webm,video/ogg,video/quicktime,.mp4,.webm,.ogg,.mov"
              className="hidden"
              onChange={(e) => handleFileSelect(target, e.target.files?.[0])}
              disabled={saving}
            />
            <div className="size-10 mx-auto mb-2 rounded-full bg-primary/10 flex items-center justify-center">
              {saving && dragTarget === target ? (
                <RefreshCw className="size-5 text-primary animate-spin" />
              ) : (
                <Upload className="size-5 text-primary" />
              )}
            </div>
            <p className="text-sm font-medium text-foreground mb-1">
              {saving && dragTarget === target ? '上传中...' : '拖拽视频到此处，或点击选择'}
            </p>
            <p className="text-xs text-muted-foreground">
              MP4 / WebM / MOV · 最大 {MAX_SIZE_MB}MB
            </p>
          </div>

          {videoInfo.isCustom && (
            <Button
              variant="outline"
              size="sm"
              className="w-full text-destructive hover:text-destructive hover:bg-destructive/10 border-destructive/30"
              onClick={() => setResetTarget(target)}
            >
              <Trash2 className="size-4 mr-1.5" />
              删除视频
            </Button>
          )}
        </CardContent>
      </Card>
    );
  };

  return (
    <div className="space-y-6">
      <PageBreadcrumb
        firstItem={{ label: adminT('admin.dashboard'), href: '/admin/dashboard', icon: 'dashboard' }}
        items={[{ label: '工厂视频' }]}
      />

      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-foreground flex items-center gap-2">
            <Video className="size-6 text-primary" />
            工厂视频管理
          </h1>
          <p className="text-sm text-muted-foreground mt-1">
            上传工厂宣传视频，可在首页和 About 页面展示
          </p>
        </div>
        <Badge
          variant="outline"
          className={settings.enabled ? 'bg-success/15 text-success border-success/30' : 'bg-muted/50'}
        >
          {settings.enabled ? (
            <>
              <CheckCircle2 className="size-3 mr-1" />
              已启用
            </>
          ) : (
            <>
              <AlertCircle className="size-3 mr-1" />
              已关闭
            </>
          )}
        </Badge>
      </div>

      {/* 设置卡片 */}
      <Card className="border-border/40 bg-card">
        <CardHeader>
          <CardTitle className="text-base flex items-center gap-2">
            <SettingsIcon className="size-4 text-primary" />
            显示设置
          </CardTitle>
          <CardDescription>控制视频在前台各页面的显示</CardDescription>
        </CardHeader>
        <CardContent className="space-y-5">
          <div className="flex items-center justify-between">
            <div className="space-y-0.5">
              <Label>启用工厂视频</Label>
              <p className="text-xs text-muted-foreground">关闭后所有页面都不显示视频</p>
            </div>
            <Switch
              checked={settings.enabled}
              onCheckedChange={(checked) => handleUpdate({ enabled: checked })}
            />
          </div>

          <div className="flex items-center justify-between">
            <div className="space-y-0.5">
              <Label>首页展示</Label>
              <p className="text-xs text-muted-foreground">在首页 Hero 下方展示视频</p>
            </div>
            <Switch
              checked={settings.showOnHome}
              onCheckedChange={(checked) => handleUpdate({ showOnHome: checked })}
              disabled={!settings.enabled}
            />
          </div>

          <div className="flex items-center justify-between">
            <div className="space-y-0.5">
              <Label>About 页面展示</Label>
              <p className="text-xs text-muted-foreground">在 About Us 页面公司介绍下方展示视频</p>
            </div>
            <Switch
              checked={settings.showOnAbout}
              onCheckedChange={(checked) => handleUpdate({ showOnAbout: checked })}
              disabled={!settings.enabled}
            />
          </div>

          <div className="border-t border-border/40 pt-5 space-y-5">
            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label>自动播放</Label>
                <p className="text-xs text-muted-foreground">进入页面时静音自动播放并循环</p>
              </div>
              <Switch
                checked={settings.autoPlay}
                onCheckedChange={(checked) => handleUpdate({ autoPlay: checked })}
              />
            </div>

            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label>显示控制条</Label>
                <p className="text-xs text-muted-foreground">鼠标悬停时显示播放/音量/全屏控件</p>
              </div>
              <Switch
                checked={settings.showControls}
                onCheckedChange={(checked) => handleUpdate({ showControls: checked })}
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="video-title">视频标题</Label>
              <Input
                id="video-title"
                value={settings.videoTitle}
                onChange={(e) => handleUpdate({ videoTitle: e.target.value })}
                placeholder="Factory Tour"
                className="max-w-md"
              />
            </div>
          </div>
        </CardContent>
      </Card>

      {/* 两个上传卡片 */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <UploadCard
          target="home"
          title="首页视频"
          desc="首页 Hero 下方展示的工厂视频"
          videoInfo={homeVideo}
          icon={Home}
        />
        <UploadCard
          target="about"
          title="About 页面视频"
          desc="About Us 页面展示的工厂视频"
          videoInfo={aboutVideo}
          icon={Building2}
        />
      </div>

      {/* 预览 */}
      {settings.enabled && (homeVideo.url || aboutVideo.url) && (
        <Card className="border-border/40 bg-card">
          <CardHeader>
            <CardTitle className="text-base flex items-center gap-2">
              <Eye className="size-4 text-primary" />
              视频预览
            </CardTitle>
            <CardDescription>与前台展示效果一致</CardDescription>
          </CardHeader>
          <CardContent className="space-y-6">
            {settings.showOnHome && homeVideo.url && (
              <div className="space-y-2">
                <p className="text-sm font-medium text-foreground">首页视频</p>
                <FactoryVideoPlayer
                  videoUrl={homeVideo.url}
                  title={settings.videoTitle}
                  posterUrl={settings.posterUrl}
                  autoPlay={false}
                  showControls={settings.showControls}
                  variant="home"
                />
              </div>
            )}
            {settings.showOnAbout && aboutVideo.url && (
              <div className="space-y-2">
                <p className="text-sm font-medium text-foreground">About 页面视频</p>
                <FactoryVideoPlayer
                  videoUrl={aboutVideo.url}
                  title={settings.videoTitle}
                  posterUrl={settings.posterUrl}
                  autoPlay={false}
                  showControls={settings.showControls}
                  variant="about"
                />
              </div>
            )}
          </CardContent>
        </Card>
      )}

      {/* 删除确认 */}
      <AlertDialog open={!!resetTarget} onOpenChange={(open) => !open && setResetTarget(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>确认删除视频？</AlertDialogTitle>
            <AlertDialogDescription>
              删除后{resetTarget === 'home' ? '首页' : 'About 页面'}将不再展示视频。
              此操作无法撤销。
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>取消</AlertDialogCancel>
            <AlertDialogAction
              className="bg-destructive hover:bg-destructive/90 text-destructive-foreground"
              onClick={() => resetTarget && handleReset(resetTarget)}
            >
              确认删除
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}
